ta":"Motivo","tipo":"texto","requerido":false,"origen":"parada.motivo","solo_si":{"campo":"resultado","igual":"No ejecutada"}}]},{"clave":"evidencia","titulo":"Evidencia","campos":[{"clave":"origen_marca","etiqueta":"Origen de la marca","tipo":"opcion","requerido":true,"origen":"parada.origen_etiqueta","opciones":["GPS del camión","GPS del celular","Marcada a mano","Sin evidencia de posición"],"nota":"El rastro de flota es autoritativo; el del teléfono corrobora."},{"clave":"doble_evidencia","etiqueta":"Doble evidencia","tipo":"booleano","requerido":false,"origen":"parada.evidencia_doble"},{"clave":"fotos","etiqueta":"Fotos","tipo":"entero","requerido":false,"origen":"parada.fotos"},{"clave":"firma","etiqueta":"Firma del receptor","tipo":"booleano","requerido":false,"origen":"parada.firmada"},{"clave":"ambigua","etiqueta":"Parada ambigua","tipo":"booleano","requerido":false,"origen":"parada.ambiguo","nota":"Hay otra parada en la misma coordenada y el GPS no las distingue."}]},{"clave":"responsables","titulo":"Responsables","campos":[{"clave":"chofer","etiqueta":"Chofer","tipo":"texto","requerido":false,"origen":"jornada.chofer"},{"clave":"vehiculo","etiqueta":"Vehículo","tipo":"texto","requerido":false,"origen":"jornada.vehiculo"},{"clave":"observaciones","etiqueta":"Observaciones","tipo":"texto_largo","requerido":false}]}]}', '', 1, 'Version inicial derivada de parada_ejecucion. A validar por CAMCA (S4).', UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE version = version;

-- La huella se calcula sobre los bytes guardados, del lado del motor, para que
-- no haya un hash escrito a mano que pueda quedar desfasado del contenido.
-- Sirve para detectar que alguien edito una definicion in situ.
UPDATE formulario_def SET esquema_sha = SHA2(esquema_json, 256) WHERE esquema_sha = '';

-- FIN
